import { readFileSync } from 'node:fs';
const cur = JSON.parse(readFileSync('contracts/openapi.json', 'utf-8'));
const base = JSON.parse(readFileSync('contracts/openapi.baseline.json', 'utf-8'));
const breaks = [];
for (const [k, t] of Object.entries(base.fields || {})) {
  if (!(k in (cur.fields || {}))) breaks.push(`required field '${k}' removed`);
  else if (cur.fields[k] !== t) breaks.push(`field '${k}' type changed ${t} -> ${cur.fields[k]}`);
}
for (const p of base.paths || []) {
  if (!((cur.paths || []).includes(p))) breaks.push(`path '${p}' removed`);
}
if (breaks.length) {
  for (const b of breaks) console.log('BREAKING: ' + b);
  process.exit(1);
}
console.log('no breaking changes');
process.exit(0);

